// #6a61f2a5 — TC-QR-01, TC-QR-02 p.1 (profile share link opens the owner's profile)
import assert from 'node:assert/strict';
import { startDriver, byText, openLink, SHARE_BASE, PARTNER, APP_ID } from '../lib/session.js';

describe('QR profile link #6a61f2a5 @ios @android @prod-safe', function () {
  let d;
  before(async () => { d = await startDriver(); });
  after(async () => { if (d) await d.deleteSession(); });

  it('TC-QR-01: cold start — link opens the app on the QR owner profile', async () => {
    await d.terminateApp(APP_ID);
    await openLink(d, SHARE_BASE + PARTNER.id);
    await (await byText(d, PARTNER.name)).waitForDisplayed({ timeout: 30000 });
    await (await byText(d, 'Joni workers rate')).waitForDisplayed({ timeout: 10000 });
  });

  it('TC-QR-01: warm start — app in background opens the profile', async () => {
    await (await byText(d, 'חיפוש')).click().catch(() => {});
    await d.background(2);
    await openLink(d, SHARE_BASE + PARTNER.id);
    await (await byText(d, PARTNER.name)).waitForDisplayed({ timeout: 20000 });
  });

  it('TC-QR-02: non-existent id shows "profile not found"', async () => {
    await openLink(d, SHARE_BASE + '999999');
    const msg = await byText(d, 'הפרופיל לא נמצא', true);
    await msg.waitForDisplayed({ timeout: 20000 });
    assert.ok(await msg.isDisplayed());
  });
});
